// Лёгкий клиентский i18n. Словари для каждого языка; английский — источник
// истины (тип Translations выводится из него, поэтому остальные обязаны иметь
// те же ключи).
import { Platform } from "@/types";

export const LANGUAGES = ["en", "es", "ru", "uk", "kk", "ar", "zh", "hi", "id", "sw", "de", "fr", "it", "pt", "uz", "tr", "fa", "vi", "bn", "ur", "pl", "ja", "ko", "th"] as const;
export type Language = (typeof LANGUAGES)[number];

// Языки с письмом справа налево: для них вёрстка зеркалится (dir="rtl").
export function isRtl(language: Language): boolean {
  return language === "ar" || language === "fa" || language === "ur";
}

